// Prepara o pedido: mede a conversa e monta as instruções.
// Contagem é trabalho de código. O modelo interpreta o que já foi contado.

const item = $input.first();
const binarios = item.binary || {};
// O campo pode chegar como 'arquivo', 'file0' ou outro nome, dependendo do cliente.
const campo = binarios.arquivo ? 'arquivo' : Object.keys(binarios)[0];
if (!campo) throw new Error('Arquivo não recebido: nenhum binário no webhook.');

// Com binaryMode 'separate' o n8n guarda o arquivo em disco e 'data' vira um id.
// O helper funciona nos dois modos; o base64 fica de reserva.
let bruto;
try {
  const buf = await this.helpers.getBinaryDataBuffer(0, campo);
  bruto = buf.toString('utf8');
} catch (e) {
  bruto = Buffer.from(binarios[campo].data, 'base64').toString('utf8');
}
if (!bruto || bruto.length < 50) throw new Error('O arquivo chegou vazio (campo ' + campo + ').');
const corpo = item.json.body || item.json || {};

const analiseId = corpo.analiseId || corpo.analysisId;
const callbackUrl = corpo.callbackUrl;
const comAvancada = String(corpo.avancada) === 'true';
const remetente = corpo.remetente || null;
if (!analiseId || !callbackUrl) throw new Error('analiseId ou callbackUrl ausente.');

let respostas = [];
try { respostas = JSON.parse(corpo.respostas || '[]'); } catch (e) { respostas = []; }

/* ---------- 1. parsing ---------- */

const IOS = /^\[(\d{1,2})\/(\d{1,2})\/(\d{2,4}),?\s+(\d{1,2}):(\d{2})(?::(\d{2}))?\s*\]\s*([^:]{1,80}):\s*([\s\S]*)$/;
const ANDROID = /^(\d{1,2})\/(\d{1,2})\/(\d{2,4}),?\s+(\d{1,2}):(\d{2})(?::(\d{2}))?\s*-\s*([^:]{1,80}):\s*([\s\S]*)$/;
const MIDIA = /(mídia oculta|midia oculta|imagem ocultada|áudio ocultado|audio ocultado|vídeo omitido|figurinha omitida|omitted)/i;
const RUIDO = /(criptografadas de ponta a ponta|esta mensagem foi apagada|você apagou esta mensagem|criou o grupo|saiu do grupo|chamada de voz perdida)/i;

const msgs = [];
for (const linha of bruto.replace(/\u200e|\u200f|\u202a|\u202c/g, '').split(/\r?\n/)) {
  const achado = IOS.exec(linha) || ANDROID.exec(linha);
  if (!achado) {
    const ultima = msgs[msgs.length - 1];
    if (ultima && linha.trim()) ultima.texto += '\n' + linha.trim();
    continue;
  }
  const [, d, m, a, h, mi, s, autor, texto] = achado;
  if (RUIDO.test(texto)) continue;
  const ano = a.length === 2 ? 2000 + Number(a) : Number(a);
  const data = new Date(ano, Number(m) - 1, Number(d), Number(h), Number(mi), Number(s || 0));
  if (isNaN(data.getTime())) continue;
  msgs.push({ data, autor: autor.trim(), texto: texto.trim(), midia: MIDIA.test(texto) });
}

if (msgs.length < 15) throw new Error('Não conseguimos ler essa conversa (só ' + msgs.length + ' mensagens reconhecidas). Início do arquivo: ' + JSON.stringify(bruto.slice(0, 120)));

/* ---------- 2. números ---------- */

const AFETO = /(amor|te amo|amo vc|saudade|carinho|meu bem|minha vida|beijo|bjo|❤|🥰|😍|😘|💕)/i;
const RISO = /(kkk|hahah|rsrs|😂|🤣)/i;
const DESCULPA = /(desculpa|desculpe|foi mal|me perdoa|perdão|perdao)/i;
const TENSAO = /(cansad|chatead|magoad|irritad|deixa pra lá|tanto faz|não quero falar|sempre a mesma coisa)/i;

const pad = (n) => String(n).padStart(2, '0');
const iso = (dt) => dt.getFullYear() + '-' + pad(dt.getMonth() + 1) + '-' + pad(dt.getDate()) + ' ' + pad(dt.getHours()) + ':' + pad(dt.getMinutes());
const mediana = (l) => { if (!l.length) return 0; const o = [...l].sort((x, y) => x - y); const k = Math.floor(o.length / 2); return o.length % 2 ? o[k] : (o[k - 1] + o[k]) / 2; };

const autores = [...new Set(msgs.map((m) => m.autor))];

const porAutor = autores.map((autor) => {
  const minhas = msgs.filter((m) => m.autor === autor);
  const txt = minhas.filter((m) => !m.midia);
  const palavras = txt.reduce((s, m) => s + m.texto.split(/\s+/).length, 0);
  return {
    autor,
    mensagens: minhas.length,
    midias: minhas.filter((m) => m.midia).length,
    palavrasPorMensagem: txt.length ? +(palavras / txt.length).toFixed(1) : 0,
    afeto: txt.filter((m) => AFETO.test(m.texto)).length,
    riso: txt.filter((m) => RISO.test(m.texto)).length,
    desculpas: txt.filter((m) => DESCULPA.test(m.texto)).length,
    tensao: txt.filter((m) => TENSAO.test(m.texto)).length,
    perguntas: txt.filter((m) => m.texto.includes('?')).length
  };
});

const primeiroDoDia = new Map();
for (const m of msgs) { const dia = iso(m.data).slice(0, 10); if (!primeiroDoDia.has(dia)) primeiroDoDia.set(dia, m.autor); }
const iniciativas = { diasComConversa: primeiroDoDia.size, porAutor: {} };
for (const a of primeiroDoDia.values()) iniciativas.porAutor[a] = (iniciativas.porAutor[a] || 0) + 1;

const esperas = {};
for (let i = 1; i < msgs.length; i++) {
  if (msgs[i - 1].autor === msgs[i].autor) continue;
  const min = (msgs[i].data - msgs[i - 1].data) / 60000;
  if (min < 0 || min > 1440) continue;
  (esperas[msgs[i].autor] = esperas[msgs[i].autor] || []).push(min);
}
const tempoResposta = {};
for (const [autor, lista] of Object.entries(esperas)) {
  tempoResposta[autor] = { respostas: lista.length, medianaMinutos: Math.round(mediana(lista)), acimaDe4h: lista.filter((v) => v > 240).length };
}

const meses = new Map();
for (const m of msgs) {
  const chave = iso(m.data).slice(0, 7);
  const mes = meses.get(chave) || { total: 0, afeto: 0, riso: 0, porAutor: {} };
  mes.total++;
  mes.porAutor[m.autor] = (mes.porAutor[m.autor] || 0) + 1;
  if (!m.midia && AFETO.test(m.texto)) mes.afeto++;
  if (!m.midia && RISO.test(m.texto)) mes.riso++;
  meses.set(chave, mes);
}

const porHora = new Array(24).fill(0);
const horasDeTensao = new Array(24).fill(0);
for (const m of msgs) { porHora[m.data.getHours()]++; if (!m.midia && TENSAO.test(m.texto)) horasDeTensao[m.data.getHours()]++; }

const silencios = [];
for (let i = 1; i < msgs.length; i++) {
  const horas = (msgs[i].data - msgs[i - 1].data) / 3600000;
  if (horas >= 24) silencios.push({ de: iso(msgs[i - 1].data), ate: iso(msgs[i].data), horas: Math.round(horas), quemVoltou: msgs[i].autor });
}
silencios.sort((a, b) => b.horas - a.horas);

const numeros = {
  periodo: { de: iso(msgs[0].data), ate: iso(msgs[msgs.length - 1].data), dias: Math.max(1, Math.round((msgs[msgs.length - 1].data - msgs[0].data) / 86400000)) },
  total: msgs.length,
  autores: porAutor,
  iniciativas,
  tempoResposta,
  porMes: [...meses.entries()].map(([mes, d]) => ({ mes, ...d })),
  porHora,
  horasDeTensao,
  silencios: silencios.slice(0, 5)
};

/* ---------- 3. amostra ---------- */
// O orçamento é gasto primeiro no fim da conversa: cortar em ordem cronológica
// jogaria fora justamente o trecho mais recente.

const LIMITE = 14000;
const texto = msgs.filter((m) => !m.midia && m.texto.length > 1);
const linhaDe = (m) => '[' + iso(m.data) + '] ' + m.autor + ': ' + m.texto.replace(/\s+/g, ' ') + '\n';
const escolhidas = new Set();
let orcamento = LIMITE;
const tentar = (lista) => { for (const m of lista) { if (escolhidas.has(m)) continue; const custo = linhaDe(m).length; if (custo > orcamento) continue; escolhidas.add(m); orcamento -= custo; } };
tentar([...texto.slice(-90)].reverse());
tentar(texto.slice(0, 25));
const meio = texto.slice(25, -90);
const passo = Math.max(1, Math.ceil(meio.length / 120));
tentar(meio.filter((_, i) => i % passo === 0));
const amostra = texto.filter((m) => escolhidas.has(m)).map(linhaDe).join('');

/* ---------- 4. instruções ---------- */

const instrucoes = `Você escreve relatórios do Entrelinhas: uma leitura de conversas de casal, feita para a pessoa que enviou o histórico.

COMO ESCREVER
- Português brasileiro, segunda pessoa ("você"), tom de amigo próximo que não julga.
- Frases curtas. Nada de jargão: não escreva "dados", "algoritmo", "IA", "análise de sentimento", "métricas", "padrão de comunicação assíncrona", "nível de engajamento".
- Nunca diga o que a outra pessoa sente ou pensa. Descreva o que ela FAZ na conversa.
- Toda afirmação forte precisa de apoio: um número dos que você recebeu, ou um trecho da conversa. Sem apoio, não afirme.
- Não invente números. Use só os que estão em NÚMEROS MEDIDOS. Se algo não foi medido, fale em termos qualitativos.
- Número entra no meio da frase, para sustentar uma observação. Nunca abra uma seção com número, e nunca liste as contagens das duas pessoas lado a lado como boletim.
  Os dois exemplos abaixo usam X, Y e NOME no lugar dos valores. Eles mostram a FORMA da frase — nunca reaproveite o conteúdo deles.
  Ruim: "NOME iniciou a conversa em X dias, enquanto NOME2 o fez em Y dias. Isso mostra que NOME é mais proativa."
  Bom: "Quem abre a conversa quase sempre é você: em X dos Y dias, a primeira mensagem foi sua. Não é falta de vontade do outro lado — é que esse papel ficou só com você."
- Só existe o que está na conversa ou nos números. Não sugira nem cite nada que não apareceu ali (academia, terapia, yoga, viagem que ninguém mencionou).
- Não presuma o gênero de quem enviou a conversa. Nada de "cansado" ou "cansada" dirigido a ela: escreva "você está cansando disso", "o que pesa em você". Vale para todo adjetivo.
- Nunca aconselhe terminar ou continuar o relacionamento. Nunca diagnostique ("narcisista", "relação abusiva", "depressão").
- Se aparecer algo grave na conversa (violência, ameaça, alguém em risco), diga isso com cuidado e sugira procurar ajuda — sem dramatizar.
- Use os nomes reais que aparecem na conversa.
- Nada de emoji no relatório.

O QUE FAZ ESTE RELATÓRIO VALER ALGUMA COISA
Quem está lendo já sabe que gosta da outra pessoa. Ela não pagou para ouvir que se amam — pagou para ver o que não conseguiu enxergar sozinha, porque estava dentro.
O valor está no mecanismo: não "vocês brigaram", mas "quando ela fica incomodada, ela para de responder e espera você perguntar".
Se todas as seis seções forem confortáveis de ler, você falhou.
O contrário também é falha: não invente crise. Se a relação está bem, diga que está bem — mas mostre COMO ela funciona, não que é bonita.
Elogio não é leitura. No relatório inteiro, no máximo uma seção pode ser positiva.

TÍTULOS
Escreva em caixa baixa, como frase — "O tom mudou em março", não "O Tom Mudou em Março".
O título é uma observação sobre esta conversa, não uma categoria de manual.
Assim, sim: "Quem começa as conversas", "O tom mudou em março", "Assuntos que ninguém termina", "Você cancela, ela remarca", "Ela cala antes de reclamar".
Assim, não, nunca: "Comunicação", "Comunicação aberta", "Afeto e riso", "Demonstrações de carinho", "Tensão no ar", "Tensão e desculpas", "Planos e encontros", "Rotina e cansaço", "Pontos de atenção", "Momentos de conexão".

O QUE ENTREGAR
O array "sections" tem exatamente 6 objetos, nesta ordem e com estes trabalhos. Não troque um pelo outro, não repita o assunto de um no outro:

1. RITMO — quem sustenta a conversa. Quem abre, quem responde rápido, quem espera.
2. MUDANÇA — o que é diferente hoje do que era no começo. Use "porMes" e as datas. Se nada mudou de verdade, diga isso com todas as letras em vez de forçar.
3. UM ATRITO CONCRETO — pegue o desentendimento mais claro da conversa. Conte o que aconteceu, o que cada um fez, e como terminou. Cite a data.
4. O MECANISMO — o que cada um faz quando alguma coisa incomoda. Quem fala na hora, quem emudece, quem desconversa, quem pede desculpa primeiro, quem cede. Este é o achado mais valioso do relatório: é o padrão que se repete e que ninguém percebe de dentro.
5. UM HÁBITO QUE PASSA BATIDO — algo que aparece várias vezes e que a pessoa provavelmente nunca notou. Um assunto que sempre morre, um horário, uma desculpa que se repete, um tema que só um dos dois traz.
6. O QUE JÁ FUNCIONA — a única seção positiva. Mostre o mecanismo que dá certo, não um elogio genérico.

Cada seção tem 2 a 4 frases e precisa de âncora: uma data, um número dos NÚMEROS MEDIDOS, ou um trecho curto entre aspas tirado da conversa. Seção sem âncora é opinião, e opinião não vale nada aqui — reescreva antes de responder.

"patternCount" é 6.

Depois, exatamente 3 ações. Cada ação precisa citar algo específico DESTA conversa: um nome que aparece nela, um assunto que ela levantou, um horário ou mês que os números mostraram. Se a ação serviria para qualquer casal do mundo, ela está errada — reescreva.

Proibido, em qualquer variação: "quebrar a rotina", "compartilhar sentimentos", "compartilhe seus sentimentos", "reconectar-se", "comunicar-se melhor", "comunicação aberta e honesta", "ter uma conversa honesta", "dedicar tempo de qualidade", "reacender a chama", "planejar atividades juntos", "encontro especial", "encontro surpresa", "jantar romântico", "fim de semana fora", "fazer perguntas mais profundas", "ser mais atento". Antes de responder, releia suas 3 ações e troque qualquer uma que caia nessa lista.

Uma boa ação nasce de uma das seis seções, principalmente da 4 ou da 5 — é o passo pequeno que quebra o mecanismo que você acabou de mostrar. Não é um presente, não é um programa romântico, não é uma resolução vaga.

A forma de uma boa ação é: [gesto pequeno e concreto] + [quando ou onde] + [o que na conversa justifica isso]. Monte a sua com o material desta conversa. Nunca copie um exemplo pronto: qualquer exemplo que você tenha visto descreve outro casal, e repetir os detalhes dele seria inventar fato sobre este.

FORMATO
Responda SÓ com JSON válido, nesta forma:
{
  "headline": "uma frase que resume a relação, direta e sem crueldade",
  "summary": "2 ou 3 frases de abertura",
  "patternCount": número de padrões encontrados,
  "sections": [
    { "title": "título curto", "body": "texto da seção", "icon": "conversa" }
  ],
  "acoes": [
    { "titulo": "ação curta", "texto": "como fazer, em 1 ou 2 frases" }
  ]${
    comAvancada
      ? `,
  "advanced": {
    "title": "Análise avançada de traição",
    "level": "baixo" | "medio" | "alto",
    "body": "3 a 5 frases"
  }`
      : ""
  }
}

"icon" é um destes: conversa, coracao, lupa, celular, presente, foguete, escudo, alerta.
${
  comAvancada
    ? `
SOBRE A SEÇÃO AVANÇADA
A pessoa pagou para saber se há sinais de envolvimento com outra pessoa. Trate isso com seriedade e com freio.
- "baixo": nada no texto sustenta essa suspeita. É a resposta mais comum e você deve dá-la sem hesitar quando for o caso.
- "medio": há mudanças de padrão que merecem uma conversa, mas têm outras explicações possíveis. Cite as duas leituras.
- "alto": vários sinais independentes apontam na mesma direção. Mesmo assim, escreva que isso não é prova de nada.
Nunca acuse ninguém. Diga o que mudou, quando mudou, e o que isso pode ou não significar.
Escreva sobre ESTA conversa. Não escreva sobre o método, não diga que "a análise não é infalível" nem que "conversas não detectam traição" — isso é falar do produto, e a pessoa pagou para ouvir sobre a relação dela.`
    : ""
}`;

const contexto = respostas.length ? respostas.map((r) => '- ' + r.pergunta + ' ' + r.resposta).join('\n') : '- Não respondeu.';

const outros = porAutor.map((a) => a.autor).filter((n) => n !== remetente);

const quemEQuem = remetente
  ? 'QUEM É QUEM\n"' + remetente + '" é quem enviou a conversa e está lendo este relatório. Escreva "você" apenas para essa pessoa e NUNCA use o nome dela no texto.'
    + (outros.length ? ' Do outro lado está ' + outros.join(' e ') + ' — chame pelo nome.' : '')
    + '\nConfira isso em cada frase: trocar os dois é o pior erro possível aqui.\n\n'
  : '';

const curta = msgs.length < 60
  ? 'AVISO: esta conversa é curta (' + msgs.length + ' mensagens). Diga isso no summary, com naturalidade, e não force conclusões grandes. Prefira observações modestas e honestas a padrões inventados para preencher espaço.\n\n'
  : '';

const pedido = `${quemEQuem}${curta}O QUE A PESSOA CONTOU ANTES DE ENVIAR\n${contexto}\n\nComece a leitura pelo que ela disse que mais pesa.\n\nNÚMEROS MEDIDOS (contados no arquivo, pode confiar)\n${JSON.stringify(numeros)}\n\nComo ler: "iniciativas.porAutor" é quantos dias cada pessoa mandou a primeira mensagem. "tempoResposta" é a mediana em minutos até responder. "porMes" mostra volume e marcas de afeto mês a mês. "porHora" e "horasDeTensao" têm 24 posições, da meia-noite às 23h. "silencios" são os maiores intervalos sem mensagem.\n\nAMOSTRA DA CONVERSA\n\n${amostra}\n\nAgora escreva o relatório em JSON.`;

return [{ json: { analiseId, callbackUrl, comAvancada, instrucoes, pedido } }];

// Confere a forma do relatório antes de devolver ao site.

const resposta = $input.first().json;
const preparo = $('Prepara o pedido').first().json;

const conteudo = resposta.choices && resposta.choices[0] && resposta.choices[0].message && resposta.choices[0].message.content;
if (!conteudo) throw new Error('Groq não devolveu conteúdo.');

let r;
try { r = JSON.parse(conteudo); } catch (e) { throw new Error('O relatório voltou fora do formato esperado.'); }

if (!Array.isArray(r.sections) || r.sections.length === 0) throw new Error('O relatório voltou sem seções.');

const ICONES = ['conversa', 'coracao', 'lupa', 'celular', 'presente', 'foguete', 'escudo', 'alerta'];
const rodizio = ['conversa', 'coracao', 'lupa', 'celular', 'presente', 'foguete'];

const sections = r.sections
  .filter((s) => s && s.title && s.body)
  .map((s, i) => ({ title: String(s.title), body: String(s.body), icon: ICONES.includes(s.icon) ? s.icon : rodizio[i % rodizio.length] }));

const acoes = Array.isArray(r.acoes)
  ? r.acoes.filter((a) => a && a.texto).map((a) => ({ titulo: String(a.titulo || ''), texto: String(a.texto) }))
  : [];

const corpo = {
  analiseId: preparo.analiseId,
  headline: String(r.headline || 'Sua análise está pronta.'),
  summary: String(r.summary || ''),
  patternCount: Number(r.patternCount) > 0 ? Math.round(Number(r.patternCount)) : sections.length,
  sections,
  acoes
};

if (preparo.comAvancada && r.advanced && r.advanced.body) {
  const nivel = String(r.advanced.level || 'baixo').toLowerCase();
  corpo.advanced = {
    title: String(r.advanced.title || 'Análise avançada de traição'),
    body: String(r.advanced.body),
    level: nivel === 'alto' || nivel === 'medio' ? nivel : 'baixo'
  };
}

return [{ json: { callbackUrl: preparo.callbackUrl, corpo } }];

// Qualquer falha vira um aviso honesto na tela da pessoa. Sem cobrança.
// Lê do webhook, e não do preparo, porque o preparo é justamente um dos que podem falhar.

const wh = $('Recebe a conversa').first().json;
const corpo = wh.body || wh || {};
const analiseId = corpo.analiseId || corpo.analysisId;
const callbackUrl = corpo.callbackUrl;
if (!callbackUrl) throw new Error('Sem callbackUrl para avisar a falha.');

const entrada = $input.first().json || {};
const detalhe = entrada.error || entrada.message || 'A leitura não foi concluída.';

return [{ json: { callbackUrl, corpo: { analiseId, erro: String(detalhe).slice(0, 200) } } }];
